"""Migrated Meridian CRM order validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _field(record: dict, column: str) -> Any:
    value = record.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    """Apply the legacy numeric coercion used by these rules."""
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Return the first matching value from a live lookup-table row."""
    if not tables:
        return ""

    rows = tables.get(table_name, [])
    if not isinstance(rows, (list, tuple)):
        return ""

    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            value = row.get(output_column, "")
            return "" if value is None else value

    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run the applicable migrated rules and return all failures."""
    old_record = old if old is not None and event == "UPDATE" else {}
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_field(record, "DISC_PCT"))
            if not (discount >= 0 and discount <= 100):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_field(record, "DISC_PCT"))
            owner_uid = _field(record, "OWNER_UID")
            role = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            passes = not (
                discount > 20 and role != "MGR" and role != "ADMIN"
            )
            if not passes:
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _field(old_record, "STAT_CD")
            status = _field(record, "STAT_CD")
            passes = not (
                old_status == "I" and status != "I" and status != "X"
            )
            if not passes:
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_field(record, "QTY"))
            if not quantity > 0:
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        # ORD-005
        if event == "INSERT":
            product_id = _field(record, "PROD_ID")
            active_flag = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active_flag != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
